Read the ascending Date/Name pairs from the active sheet. For each row, subtract the previous date for the same name (0 for the first occurrence) and write the integer day difference into C5:C28. Apply an accounting number format to the answer cells and save the workbook.

```python
import shutil
import openpyxl
from datetime import datetime, date
from openpyxl.utils.datetime import from_excel

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

def to_date(value):
    if value is None:
        return None
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if isinstance(value, (int, float)):
        try:
            return from_excel(value).date()
        except Exception:
            return None
    if isinstance(value, str):
        s = value.strip()
        if not s:
            return None
        try:
            return datetime.fromisoformat(s).date()
        except ValueError:
            pass
        try:
            return datetime.strptime(s, "%Y-%m-%d").date()
        except ValueError:
            return None
    return None

prev_date_by_name = {}
results = []
accounting_format = '_($* #,##0.00_);_($* (#,##0.00);_($* "-"??_);_(@_)'

for row in range(5, 29):
    d = to_date(vws.cell(row=row, column=1).value)
    name = vws.cell(row=row, column=2).value

    if d is None or name is None:
        days = 0
    else:
        name = str(name).strip()
        if name in prev_date_by_name:
            days = (d - prev_date_by_name[name]).days
            if days < 0:
                days = 0
        else:
            days = 0
        prev_date_by_name[name] = d

    cell = ws.cell(row=row, column=3)
    cell.value = int(days)
    cell.number_format = accounting_format
    results.append((row, name, d, days))

wb.save(OUT)

print("computed rows:", len(results))
print("first:", results[:3])
print("last:", results[-3:])
